package com.example.editor.gamification;

import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.assertThat;

class GamificationCheckerTests {
    private final GamificationChecker checker = new GamificationChecker();

    @Test void acceptsVerifiedResolutionRule() { assertThat(checker.check(definitions(), bindings(rule("core.validation.violation-resolved")), null).valid()).isTrue(); }
    @Test void rejectsRewardForQuickFixButtonPress() { assertCode(rule("core.quickfix.applied"), "UNVERIFIED_QUICK_FIX_REWARD"); }
    @Test void rejectsUnknownEventType() { assertCode(rule("custom.unknown"), "UNKNOWN_GAMIFICATION_EVENT"); }
    @Test void requiresPointTypeForPoints() { GamificationRule value = new GamificationRule("rule:1", "Rule", "core.validation.violation-resolved", "", "EQUALS", null, "", 2, "", "", "", GamificationRepeatPolicy.ONCE_PER_EVENT, 0, 0, 0, GamificationEffectKind.AWARD, true); assertCode(value, "POINT_TYPE_REQUIRED"); }
    @Test void rejectsUnknownPointType() { GamificationRule value = new GamificationRule("rule:1", "Rule", "core.validation.violation-resolved", "", "EQUALS", null, "points:missing", 2, "", "", "", GamificationRepeatPolicy.ONCE_PER_EVENT, 0, 0, 0, GamificationEffectKind.AWARD, true); assertCode(value, "UNKNOWN_RULE_POINT_TYPE"); }
    @Test void cooldownRequiresPositiveDuration() { GamificationRule value = new GamificationRule("rule:1", "Rule", "core.validation.violation-resolved", "", "EQUALS", null, "points:quality", 2, "", "", "", GamificationRepeatPolicy.COOLDOWN, 0, 0, 0, GamificationEffectKind.AWARD, true); assertCode(value, "COOLDOWN_REQUIRED"); }
    @Test void dailyLimitRequiresMaximum() { GamificationRule value = new GamificationRule("rule:1", "Rule", "core.validation.violation-resolved", "", "EQUALS", null, "points:quality", 2, "", "", "", GamificationRepeatPolicy.DAILY_LIMIT, 0, 0, 0, GamificationEffectKind.AWARD, true); assertCode(value, "DAILY_LIMIT_REQUIRED"); }
    @Test void warnsAboutUnboundedUnlimitedRule() { GamificationRule value = new GamificationRule("rule:1", "Rule", "core.validation.violation-resolved", "", "EQUALS", null, "points:quality", 2, "", "", "", GamificationRepeatPolicy.UNLIMITED, 0, 0, 0, GamificationEffectKind.AWARD, true); assertThat(checker.check(definitions(), bindings(value), null).diagnostics()).anyMatch(item -> item.code().equals("UNBOUNDED_RULE") && item.severity() == GamificationDiagnosticSeverity.WARNING); }
    @Test void detectsDuplicateRuleId() { GamificationRule value = rule("core.validation.violation-resolved"); GamificationBindingModel bindings = new GamificationBindingModel("1.0", "gamification-bindings", "metamodel", "gamification-definitions", List.of(value, value), Map.of()); assertThat(checker.check(definitions(), bindings, null).diagnostics()).anyMatch(item -> item.code().equals("DUPLICATE_GAMIFICATION_RULE")); }
    @Test void detectsUnknownLevelPointType() { GamificationDefinitionModel definitions = new GamificationDefinitionModel("1.0", "gamification-definitions", "metamodel", "Gamification", List.of(new PointTypeDefinition("points:quality", "Quality", "", 0L)), List.of(new LevelDefinition("level:one", "One", "points:missing", 10, "")), List.of(), List.of(), List.of(), Map.of()); assertThat(checker.check(definitions, bindings(rule("core.validation.violation-resolved")), null).diagnostics()).anyMatch(item -> item.code().equals("UNKNOWN_LEVEL_POINT_TYPE")); }
    @Test void detectsUnknownReward() { GamificationDefinitionModel definitions = new GamificationDefinitionModel("1.0", "gamification-definitions", "metamodel", "Gamification", List.of(new PointTypeDefinition("points:quality", "Quality", "", 0L)), List.of(new LevelDefinition("level:one", "One", "points:quality", 10, "reward:missing")), List.of(), List.of(), List.of(), Map.of()); assertThat(checker.check(definitions, bindings(rule("core.validation.violation-resolved")), null).diagnostics()).anyMatch(item -> item.code().equals("UNKNOWN_REWARD")); }
    @Test void warnsAboutRuleWithoutEffect() { GamificationRule value = new GamificationRule("rule:1", "Rule", "core.validation.violation-resolved", "", "EQUALS", null, "", 0, "", "", "", GamificationRepeatPolicy.ONCE_PER_EVENT, 0, 0, 0, GamificationEffectKind.AWARD, true); assertThat(checker.check(definitions(), bindings(value), null).diagnostics()).anyMatch(item -> item.code().equals("RULE_WITHOUT_EFFECT")); }
    @Test void rejectsDefinitionReferenceMismatch() { GamificationBindingModel value = new GamificationBindingModel("1.0", "gamification-bindings", "metamodel", "wrong-definitions", List.of(rule("core.validation.violation-resolved")), Map.of()); assertThat(checker.check(definitions(), value, null).diagnostics()).anyMatch(item -> item.code().equals("DEFINITION_REFERENCE_MISMATCH")); }
    @Test void acceptsBoundedUnlimitedRule() { GamificationRule value = new GamificationRule("rule:1", "Rule", "core.validation.violation-resolved", "", "EQUALS", null, "points:quality", 2, "", "", "", GamificationRepeatPolicy.UNLIMITED, 0, 100, 10, GamificationEffectKind.AWARD, true); assertThat(checker.check(definitions(), bindings(value), null).diagnostics()).noneMatch(item -> item.code().equals("UNBOUNDED_RULE")); }

    private void assertCode(GamificationRule rule, String code) { assertThat(checker.check(definitions(), bindings(rule), null).diagnostics()).anyMatch(item -> item.code().equals(code)); }
    private GamificationDefinitionModel definitions() { return new GamificationDefinitionModel("1.0", "gamification-definitions", "metamodel", "Gamification", List.of(new PointTypeDefinition("points:quality", "Quality", "", 0L)), List.of(), List.of(), List.of(), List.of(), Map.of()); }
    private GamificationBindingModel bindings(GamificationRule rule) { return new GamificationBindingModel("1.0", "gamification-bindings", "metamodel", "gamification-definitions", List.of(rule), Map.of()); }
    private GamificationRule rule(String eventType) { return new GamificationRule("rule:1", "Rule", eventType, "", "EQUALS", null, "points:quality", 2, "", "", "", GamificationRepeatPolicy.ONCE_PER_EVENT, 0, 100, 10, GamificationEffectKind.AWARD, true); }
}
